/* @autogenerated */
import { UserInfo } from '@shared/context/identity/user-info.model';
import { rolesAllow } from './action-roles';

const user = (roles: string[]): UserInfo => ({ authenticated: true, roles }) as UserInfo;
const anonymous = { authenticated: false } as UserInfo;

describe('rolesAllow', () => {
  it('lets everyone in without configuration or with *', () => {
    expect(rolesAllow(undefined, 'identity.user', anonymous)).toBeTrue();
    expect(rolesAllow({}, 'identity.user', anonymous)).toBeTrue();
    expect(rolesAllow({ roles: ['*'] }, 'identity.user', anonymous)).toBeTrue();
  });

  it('asks for one of the global roles', () => {
    expect(rolesAllow({ roles: ['admin', 'iam'] }, 'identity.user', user(['iam']))).toBeTrue();
    expect(rolesAllow({ roles: ['admin'] }, 'identity.user', user(['guest']))).toBeFalse();
    expect(rolesAllow({ roles: ['admin'] }, 'identity.user', anonymous)).toBeFalse();
  });

  it('hides it from everyone with an empty list', () => {
    expect(rolesAllow({ roles: [] }, 'identity.user', user(['admin']))).toBeFalse();
  });

  it('uses the roles of the entity instead of the global ones', () => {
    const config = { roles: ['admin'], entities: { 'identity.user': ['iam'], 'identity.tenant': ['*'] } };

    expect(rolesAllow(config, 'identity.user', user(['iam']))).toBeTrue();
    expect(rolesAllow(config, 'identity.user', user(['admin']))).toBeFalse();
    expect(rolesAllow(config, 'identity.tenant', anonymous)).toBeTrue();
    expect(rolesAllow(config, 'identity.role', user(['admin']))).toBeTrue();
  });
});
